"""Inert F1-02 first-order install metadata source and independent host codec.

No CLI, owner, capture, publication or installation authority. Only source_bytes()
reads a repository input, the adjacent coordinator-frozen targets JSON.
"""
import base64
import hashlib
import json
import os
from pathlib import Path
import re
import shlex
import stat
import zlib

SCHEMA = 'f102-install-metadata-v1'
PACKET_SCHEMA = 'f102-install-metadata-packet-v1'
SCOPE = 'first-order-routing-controls-only-not-install-admission'
TARGET_FILE_SHA256 = '59e3967d9110c7b451a0ba5181382eef395967bdb4945ef1ceec9561f987f153'
TARGET_SHA256 = 'a54b64bcd53987a9db18066f859d2f2d9ca02f36284f80e1636cea7a6cba2432'
INVENTORY_SHA256 = '341b9d45b330b0cd8379d7861af72e269a9224c4189bc6ccefd8bad5907acc3a'
MAX_SNAPSHOT = 2097152
MAX_PACKET = 60000
FAILURES = ('identity', 'os', 'package-lock', 'packages', 'package-state',
            'routing', 'configuration', 'handlers', 'custody', 'bounds', 'deadline', 'output')
BASE = '/var/lib/dpkg/'
CFG = '/etc/dpkg/dpkg.cfg.d'
LOCKS = (BASE + 'lock-frontend', BASE + 'lock', BASE + 'triggers/Lock')
FIXED_PACKAGES = ('apt', 'dpkg', 'libc-bin', 'man-db')
FILE_LIMITS = {BASE + 'triggers/File': 262144, BASE + 'triggers/Unincorp': 0,
               BASE + 'triggers/ldconfig': 65536, BASE + 'arch': 8192,
               BASE + 'info/format': 4096, BASE + 'diversions': 262144,
               BASE + 'statoverride': 262144, '/etc/dpkg/dpkg.cfg': 65536}
REQUIRED = (BASE + 'triggers/File', BASE + 'triggers/Unincorp')
DIRECTORIES = (BASE + 'updates', BASE + 'triggers', CFG)
META_KEYS = ('device', 'inode', 'mode', 'uid', 'gid', 'nlink', 'size', 'mtimeNs', 'ctimeNs')
PKG = r'[a-z0-9][a-z0-9+.-]{1,127}'
ARCH = r'[a-z0-9][a-z0-9-]{0,63}'
IDENTITY = PKG + r'(?::' + ARCH + r')?'
FIELDS = ('Package', 'Architecture', 'Version', 'Status', 'Multi-Arch')


class Rejected(ValueError):
    """Safe closed diagnostic, never raw parser/OS text."""


def require(ok, reason='output'):
    if not ok:
        raise Rejected(reason)


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=True,
                      allow_nan=False).encode('ascii')


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def exact(value, keys):
    require(type(value) is dict and set(value) == set(keys))


def integer(value, low=0, high=2**63-1):
    require(type(value) is int and low <= value <= high)


def matches(value, expression):
    require(type(value) is str and re.fullmatch(expression, value) is not None)


def lexical(value):
    require(type(value) is str and 0 < len(value) <= 1024 and len(value.encode('utf-8')) <= 1024)
    require(value.startswith('/') and (value == '/' or all(
        c not in ('', '.', '..') for c in value[1:].split('/'))))
    require(all(33 <= ord(c) < 127 for c in value))
    return value


def unique_json(raw, maximum):
    require(type(raw) is bytes and 0 < len(raw) <= maximum)
    def pairs(items):
        out = {}
        for key, value in items:
            require(key not in out)
            out[key] = value
        return out
    try:
        return json.loads(raw.decode('ascii'), object_pairs_hook=pairs,
                          parse_constant=lambda _: require(False))
    except (ValueError, UnicodeError, RecursionError):
        raise Rejected('output') from None


def unbase64(value, maximum):
    require(type(value) is str and len(value) <= 4 * ((maximum + 2) // 3))
    try:
        out = base64.b64decode(value, validate=True)
    except (ValueError, UnicodeError):
        raise Rejected('output') from None
    require(len(out) <= maximum and base64.b64encode(out).decode('ascii') == value)
    return out


def expand(value, maximum):
    compressed = unbase64(value, MAX_PACKET)
    try:
        inflater = zlib.decompressobj()
        raw = inflater.decompress(compressed, maximum + 1)
        require(len(raw) <= maximum and inflater.eof and not inflater.unused_data
                and not inflater.unconsumed_tail)
    except zlib.error:
        raise Rejected('output') from None
    return raw

# Fixed observation data, never executable code. Reviewed against the frozen file.
TARGET_DATA = ''
CANDIDATE_SHA256 = '495b3acfe8b4c6ed0af811decb84c776da7d4974388c4ca1b37a3e88713363f3'


def _fixed_paths():
    raw = expand(TARGET_DATA, 257735)
    require(len(raw) == 257735 and digest(raw) == TARGET_SHA256, 'bounds')
    paths = unique_json(raw, 257735)
    require(type(paths) is list and len(paths) == 5983, 'bounds')
    for path in paths:
        lexical(path)
    require(paths == sorted(set(paths)) and canonical(paths) == raw, 'bounds')
    return paths


def _check_targets(raw):
    require(len(raw) == 38966 and digest(raw) == TARGET_FILE_SHA256, 'bounds')
    value = unique_json(raw, 38966)
    exact(value, ('schema', 'candidatePlanSha256', 'data', 'encoding', 'expandedBytes',
                  'expandedSha256', 'explicitTriggers', 'pathCount', 'payloadInventorySha256'))
    require(value == {'schema': 'f102-install-trigger-targets-v1',
                     'candidatePlanSha256': CANDIDATE_SHA256, 'data': TARGET_DATA,
                     'encoding': 'zlib-base64', 'expandedBytes': 257735,
                     'expandedSha256': TARGET_SHA256, 'explicitTriggers': ['ldconfig'],
                     'pathCount': 5983, 'payloadInventorySha256': INVENTORY_SHA256}, 'bounds')
    integer(value['expandedBytes'], 257735, 257735)
    integer(value['pathCount'], 5983, 5983)
    _fixed_paths()


# Reviewable fixed guest program. Host acceptance NEVER executes these definitions.
GUEST_BODY = r'''
import base64
from contextlib import contextmanager
import fcntl
import hashlib
import json
import os
import re
import signal
import stat
import zlib

class Fault(Exception):
    pass

class Cancelled(BaseException):
    pass

def need(ok, reason='custody'):
    if not ok:
        raise Fault(reason)

def encode(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=True,
                      allow_nan=False).encode('ascii')

def sha(raw):
    return hashlib.sha256(raw).hexdigest()

def path_ok(path):
    need(type(path) is str and 0 < len(path.encode()) <= 1024 and path.startswith('/'), 'routing')
    need((path == '/' or all(p not in ('', '.', '..') for p in path[1:].split('/')))
         and all(33 <= ord(c) < 127 for c in path), 'routing')
    return path

def targets():
    need(len(TARGET_DATA) == 38504, 'bounds')
    zipped = base64.b64decode(TARGET_DATA, validate=True)
    need(base64.b64encode(zipped).decode() == TARGET_DATA, 'bounds')
    inflater = zlib.decompressobj()
    raw = inflater.decompress(zipped, 257736)
    need(len(raw) == 257735 and inflater.eof and not inflater.unused_data
         and not inflater.unconsumed_tail and sha(raw) == TARGET_SHA256, 'bounds')
    values = json.loads(raw)
    need(type(values) is list and len(values) == 5983 and values == sorted(set(values))
         and encode(values) == raw, 'bounds')
    ancestors = set()
    for value in values:
        path_ok(value)
        while value:
            ancestors.add(value)
            value = value.rsplit('/', 1)[0]
    ancestors.add('/')
    return ancestors

def version(value):
    need(type(value) is str and 0 < len(value) <= 16384, 'packages')
    parts = value.split(':', 1)
    if len(parts) == 2:
        epoch, value = parts
        need(re.fullmatch(r'[0-9]{1,10}', epoch) and int(epoch) <= 2147483647, 'packages')
    if '-' in value:
        value, revision = value.rsplit('-', 1)
        need(re.fullmatch(r'[A-Za-z0-9+.~]+', revision), 'packages')
    need(re.fullmatch(r'[0-9][A-Za-z0-9.+:~\-]*', value), 'packages')

def record(p):
    need('Package' in p and 'Status' in p and re.fullmatch(PKG, p['Package']), 'packages')
    pieces = p['Status'].split(' ')
    need(len(pieces) == 3 and pieces[0] in ('unknown', 'install', 'hold', 'deinstall', 'purge')
         and pieces[1] in ('ok', 'reinstreq') and pieces[2] in ('not-installed', 'config-files',
         'half-installed', 'unpacked', 'half-configured', 'triggers-awaited', 'triggers-pending', 'installed'), 'packages')
    need(pieces[2] in ('not-installed', 'half-installed') or 'Version' in p and 'Architecture' in p, 'packages')
    if 'Architecture' in p:
        need(re.fullmatch(ARCH, p['Architecture']) and p['Architecture'] != 'unknown', 'packages')
    if 'Version' in p:
        version(p['Version'])
    need('Multi-Arch' not in p or p['Multi-Arch'] in ('same', 'no', 'foreign', 'allowed'), 'packages')
    need(p.get('Multi-Arch') != 'same' or p.get('Architecture') not in (None, 'all'), 'packages')

def status_records(raw):
    need(type(raw) is bytes and 0 < len(raw) <= 8388608, 'bounds')
    text = raw.decode('utf-8')
    need(not any(ord(c) < 32 and c not in '\n\t' or ord(c) == 127 for c in text), 'packages')
    names = {k.lower(): k for k in FIELDS}
    kept = set(names) | {'triggers-pending', 'triggers-awaited'}
    rows, fields, current, stanza, pending = [], {}, None, 0, 0
    def finish():
        nonlocal pending
        if not fields:
            return
        p = {names[k]: v for k, v in fields.items() if k in names}
        need(all(all(32 <= ord(c) < 127 for c in v) for v in p.values()), 'packages')
        record(p)
        rows.append(p)
        need(len(rows) <= 4096, 'bounds')
        pending += any(fields.get(k, '').strip() for k in ('triggers-pending', 'triggers-awaited'))
    for line in text.split('\n'):
        length = len(line.encode('utf-8'))
        need(length <= 16384, 'bounds')
        if not line.strip(' \t'):
            finish()
            fields, current, stanza = {}, None, 0
            continue
        stanza += length + 1
        need(stanza <= 131072, 'bounds')
        if line[0] in ' \t':
            need(current is not None and current not in names, 'packages')
            if current in kept:
                fields[current] += ' ' + line.strip(' \t')
                need(len(fields[current].encode()) <= 16384, 'bounds')
        else:
            key, sep, value = line.partition(':')
            need(sep and re.fullmatch(r'[!-9;-~]+', key) and not key.startswith(('#', '-')), 'packages')
            key = key.lower()
            need(key not in fields, 'packages')
            fields[key] = value.strip(' \t') if key in kept else None
            current = key
    finish()
    rows.sort(key=lambda p: (p['Package'], p.get('Architecture', '')))
    need(rows and len({(p['Package'], p.get('Architecture', '')) for p in rows}) == len(rows), 'packages')
    state = {'originalStatusSha256': sha(raw), 'originalStatusBytes': len(raw), 'packageCount': len(rows),
             'holdCount': sum(p['Status'].split()[0] == 'hold' for p in rows),
             'brokenCount': sum(p['Status'].split()[1] != 'ok' or p['Status'].split()[2]
                                not in ('installed', 'config-files', 'not-installed') for p in rows),
             'pendingCount': pending, 'selectedPackages': {}}
    return rows, state

def registrants(raw, file_registry):
    need(raw is None or type(raw) is bytes and len(raw) <= (262144 if file_registry else 65536), 'bounds')
    if raw is None:
        return []
    need(not raw or raw.endswith(b'\n'), 'routing')
    out, seen = [], set()
    for line in raw.decode('ascii').split('\n')[:-1]:
        if line == '':
            continue
        need(len(line) <= 1022, 'routing')
        if file_registry:
            path, sep, value = line.partition(' ')
            need(sep, 'routing')
            path_ok(path)
        else:
            path, value = 'ldconfig', line
        parts = value.split('/')
        need(len(parts) in (1, 2) and (len(parts) == 1 or parts[1] in ('await', 'noawait'))
             and re.fullmatch(IDENTITY, parts[0]), 'routing')
        ident = parts[0]
        need((path, ident) not in seen, 'routing')
        seen.add((path, ident))
        out.append((path, ident))
    return out

def select(file_raw, explicit_raw, ancestors):
    interests = registrants(file_raw, True) + registrants(explicit_raw, False)
    selected = sorted({ident for path, ident in interests if path == 'ldconfig' or path in ancestors})
    need(len(selected) <= 32, 'bounds')
    return selected

def lookup(rows, ident):
    name, colon, arch = ident.partition(':')
    found = [p for p in rows if p['Package'] == name and (not colon or p.get('Architecture') == arch)]
    need(len(found) <= 1, 'handlers')
    return found[0] if found else None

def namespace(p, ident, fmt):
    need(fmt in (None, b'0\n', b'1\n'), 'handlers')
    if p is None:
        need(':' not in ident, 'handlers')
        return ident
    if p.get('Multi-Arch') == 'same':
        need(fmt == b'1\n', 'handlers')
        return p['Package'] + ':' + p['Architecture']
    return p['Package']

def stamp(info):
    return dict(zip(META_KEYS, (info.st_dev, info.st_ino, info.st_mode, info.st_uid,
                info.st_gid, info.st_nlink, info.st_size, info.st_mtime_ns, info.st_ctime_ns)))

def kind(mode):
    if stat.S_ISREG(mode):
        return 'file'
    if stat.S_ISDIR(mode):
        return 'directory'
    if stat.S_ISLNK(mode):
        return 'symlink'
    return 'other'

HANDLED = (signal.SIGTERM, signal.SIGINT, signal.SIGHUP, signal.SIGALRM)

class System:
    """Descriptor-relative fixed reads; injectable syscall adapter for private tests.

    Each slot exists before open; masking includes the hard alarm. A slot is
    detached before close, with no retry even when close has ambiguous outcome.
    """
    def __init__(self, ops=os, locking=fcntl, signals=signal):
        self.ops, self.locking, self.signals = ops, locking, signals
        self.slots, self.dirs, self.leaves, self.absent = [], {}, {}, []
        self.files, self.directories = [], []
        self.exported = 0

    @contextmanager
    def critical(self):
        old = self.signals.pthread_sigmask(signal.SIG_BLOCK, set(HANDLED))
        try:
            yield
        finally:
            self.signals.pthread_sigmask(signal.SIG_SETMASK, old)

    def identity(self):
        need(self.ops.geteuid() == self.ops.getegid() == 0
             and self.ops.environ.get('SUDO_UID') == self.ops.environ.get('SUDO_GID') == '1000', 'identity')
        return {'effectiveUid': 0, 'effectiveGid': 0, 'sudoIdentity': 'uid1000'}

    def _retain(self, path, parent, name, directory):
        need(len(self.slots) < 256, 'bounds')
        row = {'path': path, 'parent': parent, 'name': name, 'fd': None,
               'metadata': None, 'raw': None, 'entries': None, 'maximum': None}
        with self.critical():
            self.slots.append(row)
            row['fd'] = self.ops.open(name, os.O_RDONLY | os.O_NONBLOCK | os.O_NOFOLLOW | os.O_CLOEXEC
                                      | (os.O_DIRECTORY if directory else 0), dir_fd=parent)
        info = self.ops.fstat(row['fd'])
        need(info.st_uid == 0 and not info.st_mode & 0o6022 and
             (stat.S_ISDIR(info.st_mode) if directory else stat.S_ISREG(info.st_mode) and info.st_nlink == 1))
        row['metadata'] = stamp(info)
        need(stamp(self.ops.stat(name, dir_fd=parent, follow_symlinks=False)) == row['metadata'])
        return row

    def directory(self, path):
        if path in self.dirs:
            return self.dirs[path]
        need(len(self.dirs) < 64, 'bounds')
        if path == '/':
            row = self._retain('/', None, '/', True)
        else:
            parent_path, name = path.rsplit('/', 1)
            parent = self.directory(parent_path or '/')
            row = self._retain(path, parent['fd'], name, True)
        self.dirs[path] = row
        return row

    def leaf(self, path, optional=False):
        path_ok(path)
        need(path not in self.leaves)
        parent_path, name = path.rsplit('/', 1)
        parent = self.directory(parent_path)
        try:
            before = self.ops.stat(name, dir_fd=parent['fd'], follow_symlinks=False)
        except FileNotFoundError:
            need(optional)
            self.absent.append((parent['fd'], name))
            self.leaves[path] = None
            return None
        # Never reopen an already retained inode, in particular a POSIX lock.
        need(all(r['metadata'] is None or (before.st_dev, before.st_ino) !=
                 (r['metadata']['device'], r['metadata']['inode']) for r in self.slots))
        row = self._retain(path, parent['fd'], name, False)
        need(stamp(before) == row['metadata'])
        self.leaves[path] = row
        return row

    def _bytes(self, row, maximum):
        size = row['metadata']['size']
        need(0 <= size <= maximum, 'bounds')
        parts, offset = [], 0
        while offset <= size:
            chunk = self.ops.pread(row['fd'], min(65536, size + 1 - offset), offset)
            need(type(chunk) is bytes and len(chunk) <= min(65536, size + 1 - offset))
            if not chunk:
                break
            parts.append(chunk)
            offset += len(chunk)
        need(offset == size)
        raw = b''.join(parts)
        need(stamp(self.ops.fstat(row['fd'])) == row['metadata'])
        return raw

    def read(self, path, maximum, optional=False, export=False):
        if export:
            need(len(self.files) < 128, 'bounds')
        row = self.leaf(path, optional)
        raw = None
        if row is not None:
            raw = self._bytes(row, maximum)
            row['raw'], row['maximum'] = raw, maximum
        if export:
            self.exported += len(raw) if raw is not None else 0
            need(self.exported <= 2097152, 'bounds')
            self.files.append({'path': path, 'state': 'absent' if raw is None else 'present',
                'metadata': None if row is None else row['metadata'], 'bytes': None if raw is None else len(raw),
                'sha256': None if raw is None else sha(raw),
                'data': None if raw is None else base64.b64encode(raw).decode('ascii')})
        return raw

    def locks(self):
        for path in LOCKS:
            row = self.leaf(path)
            self.locking.lockf(row['fd'], fcntl.LOCK_SH | fcntl.LOCK_NB)

    def _scan(self, row, maximum):
        # scandir(fd) may share an advanced open-file-description offset.
        self.ops.lseek(row['fd'], 0, os.SEEK_SET)
        entries = []
        with self.ops.scandir(row['fd']) as iterator:
            for entry in iterator:
                need(len(entries) < maximum, 'bounds')
                name = entry.name
                need(type(name) is str and 0 < len(name.encode('utf-8')) <= 255
                     and name not in ('.', '..') and '/' not in name and '\x00' not in name)
                info = entry.stat(follow_symlinks=False)
                entries.append({'name': name, 'kind': kind(info.st_mode), 'metadata': stamp(info)})
        entries.sort(key=lambda e: e['name'])
        need(len({e['name'] for e in entries}) == len(entries))
        return entries

    def listing(self, path, maximum, optional=False):
        parent_path, name = path.rsplit('/', 1)
        parent = self.directory(parent_path)
        try:
            self.ops.stat(name, dir_fd=parent['fd'], follow_symlinks=False)
        except FileNotFoundError:
            need(optional)
            self.absent.append((parent['fd'], name))
            self.directories.append({'path': path, 'state': 'absent', 'metadata': None, 'entries': None})
            return None
        row = self.directory(path)
        entries = self._scan(row, maximum)
        row['entries'], row['maximum'] = entries, maximum
        self.directories.append({'path': path, 'state': 'present', 'metadata': row['metadata'], 'entries': entries})
        return entries

    def operating(self):
        raw = self.read('/usr/lib/os-release', 8192)
        fields = {}
        for line in raw.decode('ascii').split('\n'):
            if line.startswith(('ID=', 'VERSION_ID=')):
                key, value = line.split('=', 1)
                need(key not in fields, 'os')
                if value.startswith('"') and value.endswith('"'):
                    value = value[1:-1]
                fields[key] = value
        need(fields.get('ID') == 'debian' and re.fullmatch(r'13(?:\.[0-9]{1,3}){0,2}',
             fields.get('VERSION_ID', '')) and self.ops.uname().machine == 'x86_64', 'os')
        return {'id': 'debian', 'version': fields['VERSION_ID'], 'architecture': 'amd64'}

    def verify(self):
        for parent, name in self.absent:
            try:
                self.ops.stat(name, dir_fd=parent, follow_symlinks=False)
            except FileNotFoundError:
                continue
            raise Fault('custody')
        for row in self.slots:
            need(row['fd'] is not None and row['metadata'] is not None)
            need(stamp(self.ops.fstat(row['fd'])) == row['metadata'] and
                 stamp(self.ops.stat(row['name'], dir_fd=row['parent'], follow_symlinks=False)) == row['metadata'])
            if row['raw'] is not None:
                need(self._bytes(row, row['maximum']) == row['raw'])
            if row['entries'] is not None:
                need(self._scan(row, row['maximum']) == row['entries'])
        # A mutation during any reread/listing cannot escape later binding checks.
        for row in self.slots:
            need(stamp(self.ops.fstat(row['fd'])) == row['metadata'] and
                 stamp(self.ops.stat(row['name'], dir_fd=row['parent'], follow_symlinks=False)) == row['metadata'])
        for parent, name in self.absent:
            try:
                self.ops.stat(name, dir_fd=parent, follow_symlinks=False)
            except FileNotFoundError:
                continue
            raise Fault('custody')

    def close(self):
        failed = False
        while self.slots:
            remaining = len(self.slots)
            try:
                with self.critical():
                    row = self.slots.pop()
                    fd, row['fd'] = row['fd'], None
                    if fd is not None:
                        self.ops.close(fd)
            except BaseException:
                # No retry of detached FD, and continue draining remaining slots.
                failed = True
                if len(self.slots) == remaining:
                    break  # Cannot establish a safe close section; custody unknown.
        need(not failed)

def collect(system):
    phase, failure, value = 'identity', None, None
    try:
        identity = system.identity()
        phase = 'os'
        operating = system.operating()
        phase = 'package-lock'
        system.locks()
        phase = 'package-state'
        updates = system.listing(BASE + 'updates', 4096)
        need(updates == [], 'package-state')
        need(system.read(BASE + 'triggers/Unincorp', 0, export=True) == b'', 'package-state')
        phase = 'packages'
        rows, state = status_records(system.read(BASE + 'status', 8388608))
        phase = 'routing'
        system.listing(BASE + 'triggers', 4096)
        file_raw = system.read(BASE + 'triggers/File', 262144, export=True)
        explicit = system.read(BASE + 'triggers/ldconfig', 65536, optional=True, export=True)
        handlers = select(file_raw, explicit, targets())
        phase = 'configuration'
        for path in (BASE + 'arch', BASE + 'info/format', BASE + 'diversions', BASE + 'statoverride', '/etc/dpkg/dpkg.cfg'):
            system.read(path, FILE_LIMITS[path], optional=True, export=True)
        config = system.listing(CFG, 64, optional=True)
        accepted = [e['name'] for e in (config or []) if re.fullmatch(r'[A-Za-z0-9_-]+', e['name'])]
        need(len(accepted) <= 32, 'bounds')
        for name in accepted:
            system.read(CFG + '/' + name, 65536, export=True)
        phase = 'handlers'
        fmt_row = system.leaves[BASE + 'info/format']
        fmt = fmt_row['raw'] if fmt_row is not None else None
        need(fmt in (None, b'0\n', b'1\n'), 'handlers')
        namespaces = set()
        for name in sorted(set(FIXED_PACKAGES) | set(handlers)):
            state['selectedPackages'][name] = lookup(rows, name)
        for ident in handlers:
            ns = namespace(state['selectedPackages'][ident], ident, fmt)
            need(ns not in namespaces, 'handlers')
            namespaces.add(ns)
            for suffix in ('.triggers', '.postinst'):
                system.read(BASE + 'info/' + ns + suffix, 262144, optional=True, export=True)
        phase = 'custody'
        system.verify()
        value = {'schema': SCHEMA, 'scope': SCOPE, 'identity': identity, 'os': operating,
                 'packageState': state, 'files': sorted(system.files, key=lambda f: f['path']),
                 'directories': sorted(system.directories, key=lambda d: d['path']),
                 'handlers': handlers, 'targetSha256': TARGET_SHA256}
    except Cancelled:
        failure = 'deadline'
    except BaseException as error:
        failure = error.args[0] if isinstance(error, Fault) and error.args and error.args[0] in FAILURES else phase
    finally:
        try:
            system.close()
        except BaseException:
            failure = failure or 'custody'
    if failure:
        raise Fault(failure)
    return value

def unavailable(reason):
    need(reason in FAILURES, 'output')
    return {'schema': PACKET_SCHEMA, 'status': 'unavailable', 'firstFailure': reason,
            'encoding': 'zlib-base64', 'expandedBytes': 0, 'sha256': None, 'data': None}

def packet(value):
    raw = encode(value)
    need(0 < len(raw) <= 2097152, 'bounds')
    result = {'schema': PACKET_SCHEMA, 'status': 'observed', 'firstFailure': 'none',
              'encoding': 'zlib-base64', 'expandedBytes': len(raw), 'sha256': sha(raw),
              'data': base64.b64encode(zlib.compress(raw, 9)).decode('ascii')}
    need(len(encode(result)) <= 60000, 'bounds')
    return result

def main():
    old = {sig: signal.getsignal(sig) for sig in HANDLED}
    timer = signal.getitimer(signal.ITIMER_REAL)
    mask = signal.pthread_sigmask(signal.SIG_BLOCK, set(HANDLED))
    try:
        for sig in HANDLED:
            signal.signal(sig, lambda *_: (_ for _ in ()).throw(Cancelled()))
        signal.setitimer(signal.ITIMER_REAL, 25)
        signal.pthread_sigmask(signal.SIG_UNBLOCK, set(HANDLED))
        try:
            result = packet(collect(System()))
        except Cancelled:
            result = unavailable('deadline')
        except BaseException as error:
            reason = error.args[0] if isinstance(error, Fault) and error.args and error.args[0] in FAILURES else 'output'
            result = unavailable(reason)
        raw = encode(result)
        need(os.write(1, raw) == len(raw), 'output')
        return 0 if result['status'] == 'observed' else 3
    except BaseException:
        return 3
    finally:
        signal.pthread_sigmask(signal.SIG_BLOCK, set(HANDLED))
        signal.setitimer(signal.ITIMER_REAL, 0)
        for sig, handler in old.items():
            signal.signal(sig, handler)
        signal.setitimer(signal.ITIMER_REAL, *timer)
        signal.pthread_sigmask(signal.SIG_SETMASK, mask)

if __name__ == '__main__':
    os._exit(main())
'''


def _guest_program():
    names = ('SCHEMA', 'PACKET_SCHEMA', 'SCOPE', 'TARGET_SHA256', 'TARGET_DATA', 'FAILURES',
             'BASE', 'CFG', 'LOCKS', 'FIXED_PACKAGES', 'FILE_LIMITS', 'META_KEYS', 'PKG', 'ARCH', 'IDENTITY', 'FIELDS')
    return ('\n'.join(k + ' = ' + repr(globals()[k]) for k in names) + '\n' + GUEST_BODY).encode('ascii')


def source_bytes() -> bytes:
    """Construct the sole future guest source, checking only the adjacent input."""
    path = Path(__file__).with_name('install-metadata-targets.json')
    # A bounded no-follow read; this is the only host filesystem API in the module.
    try:
        with open(path, 'rb', opener=lambda p, flags: os.open(p, flags | os.O_NOFOLLOW | os.O_NONBLOCK)) as stream:
            raw = stream.read(38967)
        require(type(raw) is bytes, 'bounds')
        _check_targets(raw)
    except (OSError, TypeError, ValueError):
        raise Rejected('bounds') from None
    program = _guest_program()
    compressed = base64.b64encode(zlib.compress(program, 9)).decode('ascii')
    bootstrap = ("import base64,zlib,hashlib\n"
                 "d=zlib.decompressobj()\n"
                 "b=d.decompress(base64.b64decode(" + repr(compressed) + ",validate=True)," + str(len(program) + 1) + ")\n"
                 "assert len(b)==" + str(len(program)) + " and d.eof and not d.unused_data and not d.unconsumed_tail\n"
                 "assert hashlib.sha256(b).hexdigest()==" + repr(digest(program)) + "\n"
                 "exec(compile(b,'<fixed-install-metadata>','exec'))\n").encode('ascii')
    require(len(shlex.quote(bootstrap.decode('ascii')).encode('ascii')) <= 60000, 'bounds')
    return bootstrap


def source_sha256():
    return digest(source_bytes())


def _metadata(value, expected=None, protected=False):
    exact(value, META_KEYS)
    for key in META_KEYS:
        integer(value[key], 1 if key in ('inode', 'nlink') else 0)
    integer(value['mode'], 0, 0o177777)
    mode = value['mode']
    kind = ('file' if stat.S_ISREG(mode) else 'directory' if stat.S_ISDIR(mode)
            else 'symlink' if stat.S_ISLNK(mode) else 'other')
    require(expected is None or kind == expected)
    if protected:
        require(value['uid'] == 0 and not mode & 0o6022)
        require(kind == 'directory' or kind == 'file' and value['nlink'] == 1)
    return kind


def _host_package(value):
    require(type(value) is dict and set(value) <= set(FIELDS)
            and {'Package', 'Status'} <= set(value))
    for field in value.values():
        require(type(field) is str and 0 < len(field) <= 16384
                and all(32 <= ord(c) < 127 for c in field))
    matches(value['Package'], PKG)
    pieces = value['Status'].split(' ')
    require(len(pieces) == 3 and pieces[0] in ('unknown', 'install', 'hold', 'deinstall', 'purge')
            and pieces[1] in ('ok', 'reinstreq') and pieces[2] in ('not-installed', 'config-files',
            'half-installed', 'unpacked', 'half-configured', 'triggers-awaited', 'triggers-pending', 'installed'))
    require(pieces[2] in ('not-installed', 'half-installed') or
            {'Architecture', 'Version'} <= set(value))
    if 'Architecture' in value:
        matches(value['Architecture'], ARCH)
        require(value['Architecture'] != 'unknown')
    if 'Version' in value:
        rest = value['Version']
        if ':' in rest:
            epoch, rest = rest.split(':', 1)
            matches(epoch, r'[0-9]{1,10}')
            require(int(epoch) <= 2147483647)
        if '-' in rest:
            rest, revision = rest.rsplit('-', 1)
            matches(revision, r'[A-Za-z0-9+.~]+')
        matches(rest, r'[0-9][A-Za-z0-9.+:~\-]*')
    require('Multi-Arch' not in value or value['Multi-Arch'] in ('no', 'same', 'allowed', 'foreign'))
    require(value.get('Multi-Arch') != 'same' or value.get('Architecture') not in (None, 'all'))
    return pieces


def _host_interests(raw, explicit=False):
    """Independent parser of the captured dpkg1.22.22 registration format."""
    if raw is None:
        require(explicit)
        return []
    require(type(raw) is bytes and (not raw or raw.endswith(b'\n')), 'routing')
    try:
        lines = raw.decode('ascii').split('\n')[:-1]
    except UnicodeError:
        raise Rejected('routing') from None
    records = []
    keys = set()
    for line in lines:
        if not line:
            continue
        require(len(line) <= 1022, 'routing')
        if explicit:
            key, specification = 'ldconfig', line
        else:
            parts = line.split(' ')
            require(len(parts) == 2, 'routing')
            key, specification = parts
            lexical(key)
        matches(specification, IDENTITY + r'(?:/(?:await|noawait))?')
        package = specification.split('/')[0]
        require((key, package) not in keys, 'routing')
        keys.add((key, package))
        records.append((key, package))
    return records


def _host_handlers(files):
    interests = _host_interests(files[BASE + 'triggers/File'])
    interests.extend(_host_interests(files[BASE + 'triggers/ldconfig'], explicit=True))
    prefixes = {'/'}
    for path in _fixed_paths():
        prefixes.add(path)
        for index, char in enumerate(path[1:], 1):
            if char == '/':
                prefixes.add(path[:index])
    handlers = sorted({p for key, p in interests if key == 'ldconfig' or key in prefixes})
    require(len(handlers) <= 32, 'bounds')
    return handlers


def _host_namespace(ident, package, fmt):
    require(fmt in (None, b'0\n', b'1\n'), 'handlers')
    if package is None:
        require(':' not in ident, 'handlers')
        return ident
    if package.get('Multi-Arch') == 'same':
        require(fmt == b'1\n', 'handlers')
        return package['Package'] + ':' + package['Architecture']
    return package['Package']


def validate_snapshot(value):
    """Validate untrusted private snapshot without executing guest code or I/O.

    Returns the validated object; callers must retain its canonical bytes under
    their own future custody. No artifact or owner schema is supplied here.
    """
    try:
        return _validate_snapshot(value)
    except (KeyError, TypeError, ValueError, OverflowError, RecursionError):
        raise Rejected('output') from None


def _validate_snapshot(value):
    exact(value, ('schema', 'scope', 'identity', 'os', 'packageState', 'files',
                  'directories', 'handlers', 'targetSha256'))
    require(value['schema'] == SCHEMA and value['scope'] == SCOPE and value['targetSha256'] == TARGET_SHA256)
    identity = value['identity']
    exact(identity, ('effectiveUid', 'effectiveGid', 'sudoIdentity'))
    integer(identity['effectiveUid'], 0, 0)
    integer(identity['effectiveGid'], 0, 0)
    require(identity['sudoIdentity'] == 'uid1000')
    operating = value['os']
    exact(operating, ('id', 'version', 'architecture'))
    require(operating['id'] == 'debian' and operating['architecture'] == 'amd64')
    matches(operating['version'], r'13(?:\.[0-9]{1,3}){0,2}')
    handlers = value['handlers']
    require(type(handlers) is list and len(handlers) <= 32)
    for ident in handlers:
        matches(ident, IDENTITY)
    require(handlers == sorted(set(handlers)))
    state = value['packageState']
    exact(state, ('originalStatusSha256', 'originalStatusBytes', 'packageCount', 'holdCount',
                  'brokenCount', 'pendingCount', 'selectedPackages'))
    matches(state['originalStatusSha256'], r'[0-9a-f]{64}')
    integer(state['originalStatusBytes'], 1, 8388608)
    integer(state['packageCount'], 1, 4096)
    for key in ('holdCount', 'brokenCount', 'pendingCount'):
        integer(state[key], 0, state['packageCount'])
    packages = state['selectedPackages']
    exact(packages, set(FIXED_PACKAGES) | set(handlers))
    tuples, held, broken = {}, set(), set()
    for ident, package in packages.items():
        if package is None:
            continue
        pieces = _host_package(package)
        name, _, arch = ident.partition(':')
        require(package['Package'] == name and (not arch or package.get('Architecture') == arch))
        key = (name, package.get('Architecture', ''))
        require(key not in tuples or tuples[key] == package)
        tuples[key] = package
        if pieces[0] == 'hold':
            held.add(key)
        if pieces[1] != 'ok' or pieces[2] not in ('installed', 'config-files', 'not-installed'):
            broken.add(key)
        if name in packages and ':' in ident:
            require(packages[name] == package)
    require(len(tuples) <= state['packageCount'] and len(held) <= state['holdCount']
            and len(broken) <= state['brokenCount'])
    require(type(value['files']) is list and len(value['files']) <= 128)
    files, file_rows, total = {}, {}, 0
    for row in value['files']:
        exact(row, ('path', 'state', 'metadata', 'bytes', 'sha256', 'data'))
        path = lexical(row['path'])
        require(path not in files)
        file_rows[path] = row
        if row['state'] == 'absent':
            require(all(row[key] is None for key in ('metadata', 'bytes', 'sha256', 'data')))
            files[path] = None
        else:
            require(row['state'] == 'present')
            _metadata(row['metadata'], 'file', protected=True)
            integer(row['bytes'], 0, 262144)
            matches(row['sha256'], r'[0-9a-f]{64}')
            body = unbase64(row['data'], 262144)
            require(len(body) == row['bytes'] == row['metadata']['size'] and digest(body) == row['sha256'])
            total += len(body)
            require(total <= MAX_SNAPSHOT)
            files[path] = body
    require(list(files) == sorted(files) and set(FILE_LIMITS) <= set(files))
    for path, limit in FILE_LIMITS.items():
        require(files[path] is None or len(files[path]) <= limit)
    for path in REQUIRED:
        require(files[path] is not None)
    require(files[BASE + 'triggers/Unincorp'] == b'')
    directories = value['directories']
    require(type(directories) is list and len(directories) <= 64)
    require([d['path'] for d in directories] == sorted(DIRECTORIES))
    accepted = []
    for directory in directories:
        exact(directory, ('path', 'state', 'metadata', 'entries'))
        path = directory['path']
        if directory['state'] == 'absent':
            require(path == CFG and directory['metadata'] is None and directory['entries'] is None)
            continue
        require(directory['state'] == 'present')
        _metadata(directory['metadata'], 'directory', protected=True)
        entries = directory['entries']
        require(type(entries) is list and len(entries) <= (64 if path == CFG else 4096))
        names = []
        for entry in entries:
            exact(entry, ('name', 'kind', 'metadata'))
            name = entry['name']
            require(type(name) is str and 0 < len(name.encode('utf-8')) <= 255
                    and name not in ('.', '..') and '/' not in name and '\x00' not in name)
            require(_metadata(entry['metadata']) == entry['kind'])
            names.append(name)
            leaf = path + '/' + name
            if path == CFG and re.fullmatch(r'[A-Za-z0-9_-]+', name):
                accepted.append(leaf)
                require(leaf in files and files[leaf] is not None and entry['kind'] == 'file')
            if leaf in files:
                require(files[leaf] is not None and file_rows[leaf]['metadata'] == entry['metadata'])
        require(names == sorted(set(names)))
        if path == BASE + 'updates':
            require(not names)
        for leaf in files:
            if leaf.rsplit('/', 1)[0] == path:
                require((leaf.rsplit('/', 1)[1] in names) == (files[leaf] is not None))
        if path == BASE + 'triggers':
            require({'Lock', 'File', 'Unincorp'} <= set(names))
            lock = next(e for e in entries if e['name'] == 'Lock')
            _metadata(lock['metadata'], 'file', protected=True)
    require(len(accepted) <= 32)
    for path in accepted:
        require(len(files[path]) <= 65536)
    require(_host_handlers(files) == handlers)
    expected = set(FILE_LIMITS) | set(accepted)
    namespaces = set()
    for ident in handlers:
        namespace = _host_namespace(ident, packages[ident], files[BASE + 'info/format'])
        require(namespace not in namespaces)
        namespaces.add(namespace)
        for suffix in ('.triggers', '.postinst'):
            expected.add(BASE + 'info/' + namespace + suffix)
    # Even no-handler snapshots must reject an unknown info format.
    require(files[BASE + 'info/format'] in (None, b'0\n', b'1\n'))
    require(set(files) == expected)
    require(len(canonical(value)) <= MAX_SNAPSHOT, 'bounds')
    return value


def unavailable(reason):
    require(reason in FAILURES)
    return {'schema': PACKET_SCHEMA, 'status': 'unavailable', 'firstFailure': reason,
            'encoding': 'zlib-base64', 'expandedBytes': 0, 'sha256': None, 'data': None}


def encode_packet(snapshot):
    """Encode independently validated snapshot, deterministically; never dispatch."""
    validate_snapshot(snapshot)
    raw = canonical(snapshot)
    packet = {'schema': PACKET_SCHEMA, 'status': 'observed', 'firstFailure': 'none',
              'encoding': 'zlib-base64', 'expandedBytes': len(raw), 'sha256': digest(raw),
              'data': base64.b64encode(zlib.compress(raw, 9)).decode('ascii')}
    result = canonical(packet)
    require(len(result) <= MAX_PACKET, 'bounds')
    return result


def decode_packet(raw: bytes, code: int) -> tuple[dict, dict | None, bytes | None]:
    """Return (packet, snapshot-or-None, canonical-bytes-or-None)."""
    try:
        packet = unique_json(raw, MAX_PACKET)
        exact(packet, ('schema', 'status', 'firstFailure', 'encoding', 'expandedBytes', 'sha256', 'data'))
        require(packet['schema'] == PACKET_SCHEMA and packet['encoding'] == 'zlib-base64')
        integer(code, 0, 3)
        integer(packet['expandedBytes'], 0, MAX_SNAPSHOT)
        require(canonical(packet) == raw)
        if packet['status'] == 'unavailable':
            require(code == 3 and packet['firstFailure'] in FAILURES and packet['expandedBytes'] == 0
                    and packet['sha256'] is None and packet['data'] is None)
            return packet, None, None
        require(packet['status'] == 'observed' and code == 0 and packet['firstFailure'] == 'none'
                and packet['expandedBytes'] > 0)
        matches(packet['sha256'], r'[0-9a-f]{64}')
        snapshot_raw = expand(packet['data'], packet['expandedBytes'])
        require(len(snapshot_raw) == packet['expandedBytes'] and digest(snapshot_raw) == packet['sha256'])
        snapshot = unique_json(snapshot_raw, MAX_SNAPSHOT)
        require(canonical(snapshot) == snapshot_raw)
        validate_snapshot(snapshot)
        return packet, snapshot, snapshot_raw
    except (KeyError, TypeError, ValueError, OverflowError, RecursionError):
        raise Rejected('output') from None
